INSERT INTO feature VALUES('io-theory','runtime','The IO of a program as a theory, with a model in the source',NULL,'partial','notable',NULL,'`std.io` states the IO of a program one time as the theory `Io.Eff`: a read, a write and `close_file`, each of which gives its continuation a completion endpoint. The buffer of a read or a write moves into the operation and comes back with its completion, and an error of a model is a negative count at the endpoint. A program over the theory names no model. `Scripted` is the model with no kernel: a forked process in the source answers each operation from a tape of input and output, with a buffer as a list of bytes. `Hosted` is the blocking model over the standard streams of the host: a read of the file 0 is one `read_bytes`, and a write to the file 1 is one `write_bytes`. `copy` moves its input to its output under each of the two models: under `Scripted` in `runs` items, and under `Hosted` from `main`, which a test of the driver gives 64 KiB through a pipe. A model over the ring is owed.',NULL,'library/std/src/io.gandr corpus/model/io/copy.gandr',NULL,'#7844');
